private void visit(List<List<Integer>> adj, int u, boolean[] visited, List<Integer> order) {
    visited[u] = true;
    order.add(u); // pre-order: record u before its neighbours
    for (int v : adj.get(u)) {
        if (!visited[v]) visit(adj, v, visited, order); // go deep first
    }
}

function numIslands(grid) {
  const rows = grid.length, cols = grid[0].length;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let count = 0;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r][c] !== '1') continue;
      count++; // unvisited land = a brand-new island
      grid[r][c] = '0'; // sink it so it is never counted again
      const stack = [[r, c]];
      while (stack.length > 0) {
        const [cr, cc] = stack.pop();
        for (const [dr, dc] of dirs) {
          const nr = cr + dr, nc = cc + dc;
          if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] === '1') {
            grid[nr][nc] = '0'; // sink when pushed, so no cell is pushed twice
            stack.push([nr, nc]);
          }
        }
      }
    }
  }
  return count;
}

