def can_finish(num_courses: int, prerequisites: list[list[int]]) -> bool:
    adj = [[] for _ in range(num_courses)]
    for course, pre in prerequisites:
        adj[pre].append(course)  # edge pre -> course
    state = [0] * num_courses  # 0 = unvisited, 1 = visiting, 2 = done

    def has_cycle(u: int) -> bool:
        if state[u] == 1:
            return True  # back edge to a node on the current path
        if state[u] == 2:
            return False  # already fully explored, known safe
        state[u] = 1
        for v in adj[u]:
            if has_cycle(v):
                return True
        state[u] = 2
        return False

    return not any(has_cycle(u) for u in range(num_courses))

public boolean canFinish(int numCourses, int[][] prerequisites) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());
    for (int[] p : prerequisites) adj.get(p[1]).add(p[0]); // edge pre -> course
    int[] state = new int[numCourses]; // 0 = unvisited, 1 = visiting, 2 = done
    for (int u = 0; u < numCourses; u++) {
        if (hasCycle(u, adj, state)) return false;
    }
    return true;
}

private boolean hasCycle(int u, List<List<Integer>> adj, int[] state) {
    if (state[u] == 1) return true; // back edge to a node on the current path
    if (state[u] == 2) return false; // already fully explored, known safe
    state[u] = 1;
    for (int v : adj.get(u)) {
        if (hasCycle(v, adj, state)) return true;
    }
    state[u] = 2;
    return false;
}

function findOrder(numCourses, prerequisites) {
  const adj = Array.from({ length: numCourses }, () => []);
  const indegree = new Array(numCourses).fill(0);
  for (const [course, pre] of prerequisites) {
    adj[pre].push(course); // pre must come before course
    indegree[course]++;
  }
  const queue = [];
  for (let u = 0; u < numCourses; u++) {
    if (indegree[u] === 0) queue.push(u); // no prerequisites left
  }
  const order = [];
  let head = 0;
  while (head < queue.length) {
    const u = queue[head++];
    order.push(u); // take course u
    for (const v of adj[u]) {
      indegree[v]--; // one prerequisite of v is now satisfied
      if (indegree[v] === 0) queue.push(v);
    }
  }
  return order.length === numCourses ? order : []; // leftovers sit on or behind a cycle
}

public int[] findOrder(int numCourses, int[][] prerequisites) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());
    int[] indegree = new int[numCourses];
    for (int[] p : prerequisites) {
        adj.get(p[1]).add(p[0]); // pre must come before course
        indegree[p[0]]++;
    }
    Deque<Integer> queue = new ArrayDeque<>();
    for (int u = 0; u < numCourses; u++) {
        if (indegree[u] == 0) queue.offer(u); // no prerequisites left
    }
    int[] order = new int[numCourses];
    int taken = 0;
    while (!queue.isEmpty()) {
        int u = queue.poll();
        order[taken++] = u; // take course u
        for (int v : adj.get(u)) {
            if (--indegree[v] == 0) queue.offer(v); // last prerequisite of v satisfied
        }
    }
    return taken == numCourses ? order : new int[0]; // leftovers sit on or behind a cycle
}

function countComponents(n, edges) {
  const parent = Array.from({ length: n }, (_, i) => i); // every node is its own root
  const size = new Array(n).fill(1);
  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]]; // path halving: skip a level
      x = parent[x];
    }
    return x;
  }
  let components = n;
  for (const [a, b] of edges) {
    let ra = find(a), rb = find(b);
    if (ra === rb) continue; // already connected: this edge adds no new link
    if (size[ra] < size[rb]) [ra, rb] = [rb, ra]; // attach the smaller tree under the larger
    parent[rb] = ra;
    size[ra] += size[rb];
    components--; // two components merged into one
  }
  return components;
}

def count_components(n: int, edges: list[list[int]]) -> int:
    parent = list(range(n))  # every node is its own root
    size = [1] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path halving: skip a level
            x = parent[x]
        return x

    components = n
    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            continue  # already connected: this edge adds no new link
        if size[ra] < size[rb]:
            ra, rb = rb, ra  # attach the smaller tree under the larger
        parent[rb] = ra
        size[ra] += size[rb]
        components -= 1  # two components merged into one
    return components

public int countComponents(int n, int[][] edges) {
    int[] parent = new int[n], size = new int[n];
    for (int i = 0; i < n; i++) {
        parent[i] = i; // every node is its own root
        size[i] = 1;
    }
    int components = n;
    for (int[] e : edges) {
        int ra = find(parent, e[0]), rb = find(parent, e[1]);
        if (ra == rb) continue; // already connected: this edge adds no new link
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; } // smaller tree under larger
        parent[rb] = ra;
        size[ra] += size[rb];
        components--; // two components merged into one
    }
    return components;
