class MinHeap { // items are [dist, node], ordered by dist
  constructor() { this.a = []; }
  get size() { return this.a.length; }
  push(item) {
    const a = this.a;
    a.push(item);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p][0] <= a[i][0]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop() {
    const a = this.a, top = a[0], last = a.pop();
    if (a.length > 0) {
      a[0] = last;
      let i = 0;
      while (true) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l][0] < a[m][0]) m = l;
        if (r < a.length && a[r][0] < a[m][0]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

function networkDelayTime(times, n, k) {
  const adj = Array.from({ length: n + 1 }, () => []); // nodes are 1..n
  for (const [u, v, w] of times) adj[u].push([v, w]);
  const dist = new Array(n + 1).fill(Infinity);
  dist[k] = 0;
  const heap = new MinHeap();
  heap.push([0, k]);
  while (heap.size > 0) {
    const [d, u] = heap.pop(); // closest node not yet settled
    if (d > dist[u]) continue; // stale entry: u was already settled with a shorter time
    for (const [v, w] of adj[u]) {
      if (d + w < dist[v]) {
        dist[v] = d + w; // relax edge u -> v
        heap.push([dist[v], v]);
      }
    }
  }
  let answer = 0;
  for (let i = 1; i <= n; i++) answer = Math.max(answer, dist[i]);
  return answer === Infinity ? -1 : answer; // the signal arrives when the farthest node hears it
}

