def network_delay_time(times: list[list[int]], n: int, k: int) -> int:
    adj = [[] for _ in range(n + 1)]  # nodes are 1..n
    for u, v, w in times:
        adj[u].append((v, w))
    dist = [float('inf')] * (n + 1)
    dist[k] = 0
    heap = [(0, k)]
    while heap:
        d, u = heapq.heappop(heap)  # closest node not yet settled
        if d > dist[u]:
            continue  # stale entry: u was already settled with a shorter time
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v] = d + w  # relax edge u -> v
                heapq.heappush(heap, (dist[v], v))
    answer = max(dist[1:])
    return -1 if answer == float('inf') else answer  # the farthest node decides

public int networkDelayTime(int[][] times, int n, int k) {
    List<List<int[]>> adj = new ArrayList<>();
    for (int i = 0; i <= n; i++) adj.add(new ArrayList<>()); // nodes are 1..n
    for (int[] t : times) adj.get(t[0]).add(new int[] {t[1], t[2]});
    int[] dist = new int[n + 1];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[k] = 0;
    PriorityQueue<int[]> heap = new PriorityQueue<>((x, y) -> Integer.compare(x[0], y[0]));
    heap.offer(new int[] {0, k});
    while (!heap.isEmpty()) {
        int[] top = heap.poll(); // closest node not yet settled
        int d = top[0], u = top[1];
        if (d > dist[u]) continue; // stale entry: u was already settled with a shorter time
        for (int[] e : adj.get(u)) {
            int v = e[0], w = e[1];
            if (d + w < dist[v]) {
                dist[v] = d + w; // relax edge u -> v
                heap.offer(new int[] {dist[v], v});
            }
        }
    }
    int answer = 0;
    for (int i = 1; i <= n; i++) answer = Math.max(answer, dist[i]);
    return answer == Integer.MAX_VALUE ? -1 : answer; // the farthest node decides
}

function minCostConnectPoints(points) {
  const n = points.length;
  const inTree = new Array(n).fill(false);
  const minDist = new Array(n).fill(Infinity); // cheapest edge from the tree to each point
  minDist[0] = 0; // start the tree from point 0
  let total = 0;
  for (let added = 0; added < n; added++) {
    let u = -1;
    for (let i = 0; i < n; i++) { // pick the closest point not yet in the tree
      if (!inTree[i] && (u === -1 || minDist[i] < minDist[u])) u = i;
    }
    inTree[u] = true;
    total += minDist[u]; // pay for the cheapest link that reaches u
    for (let v = 0; v < n; v++) { // u may offer cheaper links to the rest
      if (!inTree[v]) {
        const d = Math.abs(points[u][0] - points[v][0]) + Math.abs(points[u][1] - points[v][1]);
        if (d < minDist[v]) minDist[v] = d;
      }
    }
  }
  return total;
}

