function pacificAtlantic(heights) {
  const rows = heights.length, cols = heights[0].length;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  // Reverse flow: start at the ocean and climb to neighbours that are at least as high.
  function reach(starts) {
    const seen = Array.from({ length: rows }, () => new Array(cols).fill(false));
    const queue = [];
    for (const [r, c] of starts) {
      if (seen[r][c]) continue; // corners sit on two edges
      seen[r][c] = true;
      queue.push([r, c]);
    }
    for (let head = 0; head < queue.length; head++) {
      const [r, c] = queue[head];
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr < 0 || nc < 0 || nr >= rows || nc >= cols || seen[nr][nc]) continue;
        if (heights[nr][nc] < heights[r][c]) continue; // water cannot flow uphill into (r, c)
        seen[nr][nc] = true;
        queue.push([nr, nc]);
      }
    }
    return seen;
  }
  const pacificStarts = [], atlanticStarts = [];
  for (let r = 0; r < rows; r++) {
    pacificStarts.push([r, 0]); // left edge touches the Pacific
    atlanticStarts.push([r, cols - 1]); // right edge touches the Atlantic
  }
  for (let c = 0; c < cols; c++) {
    pacificStarts.push([0, c]); // top edge: Pacific
    atlanticStarts.push([rows - 1, c]); // bottom edge: Atlantic
  }
  const pacific = reach(pacificStarts), atlantic = reach(atlanticStarts);
  const result = [];
  for (let r = 0; r < rows; r++)
    for (let c = 0; c < cols; c++)
      if (pacific[r][c] && atlantic[r][c]) result.push([r, c]); // reaches both oceans
  return result;
}

from collections import deque


def pacific_atlantic(heights: list[list[int]]) -> list[list[int]]:
    rows, cols = len(heights), len(heights[0])

    def reach(starts: list[tuple[int, int]]) -> set[tuple[int, int]]:
        # Reverse flow: start at the ocean and climb to neighbours that are at least as high.
        seen = set(starts)
        queue = deque(seen)
        while queue:
            r, c = queue.popleft()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in seen:
                    if heights[nr][nc] >= heights[r][c]:  # water can flow from (nr, nc) to (r, c)
                        seen.add((nr, nc))
                        queue.append((nr, nc))
        return seen

    pacific = reach([(r, 0) for r in range(rows)] + [(0, c) for c in range(cols)])
    atlantic = reach([(r, cols - 1) for r in range(rows)] + [(rows - 1, c) for c in range(cols)])
    return [[r, c] for r in range(rows) for c in range(cols)
            if (r, c) in pacific and (r, c) in atlantic]

public List<List<Integer>> pacificAtlantic(int[][] heights) {
    int rows = heights.length, cols = heights[0].length;
    boolean[][] pacific = new boolean[rows][cols], atlantic = new boolean[rows][cols];
    Deque<int[]> pq = new ArrayDeque<>(), aq = new ArrayDeque<>();
    for (int r = 0; r < rows; r++) {
        mark(pacific, pq, r, 0); // left edge touches the Pacific
        mark(atlantic, aq, r, cols - 1); // right edge touches the Atlantic
    }
    for (int c = 0; c < cols; c++) {
        mark(pacific, pq, 0, c); // top edge: Pacific
        mark(atlantic, aq, rows - 1, c); // bottom edge: Atlantic
    }
    reach(heights, pacific, pq);
    reach(heights, atlantic, aq);
    List<List<Integer>> result = new ArrayList<>();
    for (int r = 0; r < rows; r++)
        for (int c = 0; c < cols; c++)
            if (pacific[r][c] && atlantic[r][c]) result.add(List.of(r, c));
    return result;
}

private void mark(boolean[][] seen, Deque<int[]> queue, int r, int c) {
    if (seen[r][c]) return; // corners sit on two edges
    seen[r][c] = true;
    queue.add(new int[] {r, c});
}

private void reach(int[][] h, boolean[][] seen, Deque<int[]> queue) { // reverse flow
    int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    while (!queue.isEmpty()) {
        int[] cell = queue.poll();
        for (int[] d : dirs) {
            int nr = cell[0] + d[0], nc = cell[1] + d[1];
            if (nr < 0 || nc < 0 || nr >= h.length || nc >= h[0].length || seen[nr][nc]) continue;
            if (h[nr][nc] < h[cell[0]][cell[1]]) continue; // water cannot flow uphill
            seen[nr][nc] = true;
            queue.add(new int[] {nr, nc});
        }
    }
}

function validTree(n, edges) {
  if (edges.length !== n - 1) return false; // a tree on n nodes has exactly n - 1 edges
  const parent = Array.from({ length: n }, (_, i) => i); // every node starts as its own root
  const size = new Array(n).fill(1);
  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]]; // path halving: skip a level
      x = parent[x];
    }
    return x;
  }
  for (const [a, b] of edges) {
    let ra = find(a), rb = find(b);
    if (ra === rb) return false; // a and b are already connected: this edge closes a cycle
    if (size[ra] < size[rb]) [ra, rb] = [rb, ra]; // hang the smaller tree under the larger
    parent[rb] = ra;
    size[ra] += size[rb];
  }
  return true; // n - 1 edges and no cycle, so the graph is also connected
}

def valid_tree(n: int, edges: list[list[int]]) -> bool:
    if len(edges) != n - 1:
        return False  # a tree on n nodes has exactly n - 1 edges
    parent = list(range(n))  # every node starts as its own root
    size = [1] * n

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]  # path halving: skip a level
            x = parent[x]
        return x

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            return False  # a and b are already connected: this edge closes a cycle
        if size[ra] < size[rb]:
            ra, rb = rb, ra  # hang the smaller tree under the larger
        parent[rb] = ra
        size[ra] += size[rb]
    return True  # n - 1 edges and no cycle, so the graph is also connected

public boolean validTree(int n, int[][] edges) {
    if (edges.length != n - 1) return false; // a tree on n nodes has exactly n - 1 edges
    int[] parent = new int[n], size = new int[n];
    for (int i = 0; i < n; i++) {
        parent[i] = i; // every node starts as its own root
        size[i] = 1;
    }
    for (int[] e : edges) {
        int ra = find(parent, e[0]), rb = find(parent, e[1]);
        if (ra == rb) return false; // already connected: this edge closes a cycle
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; } // smaller tree under larger
        parent[rb] = ra;
        size[ra] += size[rb];
    }
    return true; // n - 1 edges and no cycle, so the graph is also connected
}

