function ladderLength(beginWord, endWord, wordList) {
  if (!wordList.includes(endWord)) return 0;
  const len = beginWord.length;
  const buckets = new Map(); // wildcard pattern like "c*t" -> every word that matches it
  for (const w of [beginWord, ...wordList]) {
    for (let i = 0; i < len; i++) {
      const p = w.slice(0, i) + '*' + w.slice(i + 1);
      if (!buckets.has(p)) buckets.set(p, []);
      buckets.get(p).push(w);
    }
  }
  const visited = new Set([beginWord]);
  let queue = [beginWord];
  for (let steps = 1; queue.length > 0; steps++) { // steps = words in the ladder so far
    const next = [];
    for (const word of queue) {
      if (word === endWord) return steps;
      for (let i = 0; i < len; i++) {
        const p = word.slice(0, i) + '*' + word.slice(i + 1);
        for (const nb of buckets.get(p)) {
          if (!visited.has(nb)) {
            visited.add(nb); // mark when enqueued, so no word is queued twice
            next.push(nb);
          }
        }
        buckets.set(p, []); // all its words are visited now: never scan this bucket again
      }
    }
    queue = next;
  }
  return 0; // the queue ran dry before reaching endWord
}

from collections import defaultdict


def ladder_length(begin_word: str, end_word: str, word_list: list[str]) -> int:
    if end_word not in word_list:
        return 0
    n = len(begin_word)
    buckets = defaultdict(list)  # wildcard pattern like "c*t" -> every word that matches it
    for w in [begin_word, *word_list]:
        for i in range(n):
            buckets[w[:i] + '*' + w[i + 1:]].append(w)
    visited = {begin_word}
    queue = [begin_word]
    steps = 1  # words in the ladder so far
    while queue:
        nxt = []
        for word in queue:
            if word == end_word:
                return steps
            for i in range(n):
                p = word[:i] + '*' + word[i + 1:]
                for nb in buckets[p]:
                    if nb not in visited:
                        visited.add(nb)  # mark when enqueued, so no word is queued twice
                        nxt.append(nb)
                buckets[p] = []  # all its words are visited now: never scan this bucket again
        queue = nxt
        steps += 1
    return 0  # the queue ran dry before reaching end_word

public int ladderLength(String beginWord, String endWord, List<String> wordList) {
    if (!wordList.contains(endWord)) return 0;
    int len = beginWord.length();
    Map<String, List<String>> buckets = new HashMap<>(); // "c*t" -> every word that matches it
    List<String> all = new ArrayList<>(wordList);
    all.add(beginWord);
    for (String w : all) {
        for (int i = 0; i < len; i++) {
            String p = w.substring(0, i) + '*' + w.substring(i + 1);
            buckets.computeIfAbsent(p, k -> new ArrayList<>()).add(w);
        }
    }
    Set<String> visited = new HashSet<>(List.of(beginWord));
    List<String> queue = List.of(beginWord);
    for (int steps = 1; !queue.isEmpty(); steps++) { // steps = words in the ladder so far
        List<String> next = new ArrayList<>();
        for (String word : queue) {
            if (word.equals(endWord)) return steps;
            for (int i = 0; i < len; i++) {
                String p = word.substring(0, i) + '*' + word.substring(i + 1);
                for (String nb : buckets.get(p))
                    if (visited.add(nb)) next.add(nb); // add() is false if already visited
                buckets.put(p, List.of()); // all its words are visited now: never scan it again
            }
        }
        queue = next;
    }
    return 0; // the queue ran dry before reaching endWord
}

function alienOrder(words) {
  const adj = new Map();
  const inDegree = new Map();
  for (const w of words) {
    for (const ch of w) {
      if (!adj.has(ch)) {
        adj.set(ch, new Set());
        inDegree.set(ch, 0);
      }
    }
  }

  for (let i = 0; i < words.length - 1; i++) {
    const w1 = words[i], w2 = words[i + 1];
    if (w1.length > w2.length && w1.startsWith(w2)) return "";
    const len = Math.min(w1.length, w2.length);
    for (let j = 0; j < len; j++) {
      if (w1[j] !== w2[j]) {
        if (!adj.get(w1[j]).has(w2[j])) {
          adj.get(w1[j]).add(w2[j]);
          inDegree.set(w2[j], inDegree.get(w2[j]) + 1);
        }
        break;
      }
    }
  }

  const queue = [];
  for (const [ch, deg] of inDegree) {
    if (deg === 0) queue.push(ch);
  }

  const res = [];
  while (queue.length > 0) {
    const u = queue.shift();
    res.push(u);
    for (const v of adj.get(u)) {
      inDegree.set(v, inDegree.get(v) - 1);
      if (inDegree.get(v) === 0) queue.push(v);
    }
  }

  return res.length === inDegree.size ? res.join("") : "";
}

